actions.script:
const out = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#NotesList').parameters({text: text || null, tag: tag || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {wikiSpaceId: out.wikiSpaceId, noteList: out.noteList, tagList: out.tagList,
    totalCount: out.totalCount})

const out = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageView').parameter('wikiPageId', wikiPageId || '').call()
if (!ec.message.hasError() && !out.page?.isMyNotes) ec.message.addError(ec.l10n.localize('Note not found'))
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {page: out.page, failedParts: out.failedParts})

const out = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#VersionDiff').parameters({wikiPageId: wikiPageId || '',
    fromVersionName: fromVersionName || null, toVersionName: toVersionName || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {fromShort: out.fromShort, toShort: out.toShort, html: out.html, stats: out.stats})

const page = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageRef').parameters({wikiPageId: wikiPageId || '', need: 'update'}).call()
if (!ec.message.hasError() && !page?.isMyNotes) ec.message.addError(ec.l10n.localize('Note not found'))
if (ec.message.hasError()) { ec.web.sendJsonResponse({}); return }
const out = ec.service.sync().name('ironstone.commons.KnowledgeServices.save#Page').parameters({wikiPageId: wikiPageId, pageText: pageText ?? '',
    versionNote: versionNote || null, baseVersionName: baseVersionName || null, force: String(force) === 'true', collab: String(collab) === 'true'}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {versionName: out.versionName, currentVersionName: out.currentVersionName,
    conflict: out.conflict, conflictText: out.conflictText, savedText: out.savedText,
    messageInfos: versionNote && out.versionName ? [{type: 'success', message: ec.l10n.localize('Version saved')}] : []})

const out = ec.service.sync().name('ironstone.commons.KnowledgeServices.set#PagePinned').parameters({wikiPageId: wikiPageId || '',
    pinned: String(pinned) === 'true'}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {pinned: out.pinned})

const out = ec.service.sync().name('ironstone.commons.KnowledgeServices.move#Page').parameters({wikiPageId: wikiPageId || '',
    toWikiSpaceId: toWikiSpaceId || '', toParentPath: toParentPath || '', toPageName: toPageName || null, versionNote: versionNote || null}).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse({}); return }
const link = '/qapps/Commons/Knowledge?wikiPageId=' + encodeURIComponent(wikiPageId)
ec.web.sendJsonResponse({wikiSpaceId: out.wikiSpaceId, pagePath: out.pagePath, replayed: out.replayed, versionCount: out.versionCount,
    messageInfos: [{type: 'success', message: ec.l10n.localize('Moved to the space'), link: link, linkText: ec.l10n.localize('Open the page')}]})

// the drop-down's value is entity|id
const value = String(record || '')
const bar = value.indexOf('|')
const entityName = bar > 0 ? value.substring(0, bar) : ''
const id = bar > 0 ? value.substring(bar + 1) : ''
ec.service.sync().name('ironstone.commons.KnowledgeServices.link#PageRecord').parameters({wikiPageId: wikiPageId || '',
    recordEntityName: entityName || '', recordId: id || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {messageInfos: [{type: 'success', message: ec.l10n.localize('Linked')}]})
